mapper.insert:
INSERT INTO material_zip_imports (
    user_id, course_id, material_type, original_filename, storage_path,
    size_bytes, file_hash, status, entry_count, selectable_count, expires_at
) VALUES (
    #{userId}, #{courseId}, #{materialType}, #{originalFilename}, #{storagePath},
    #{sizeBytes}, #{fileHash}, #{status}, #{entryCount}, #{selectableCount}, #{expiresAt}
)

mapper.select:
SELECT * FROM material_zip_imports
 WHERE user_id = #{userId}
 ORDER BY import_id DESC
 LIMIT #{limit}

mapper.update:
UPDATE material_zip_imports
   SET status = #{status}, entry_count = #{entryCount}, selectable_count = #{selectableCount}
 WHERE import_id = #{importId}

mapper.select:
SELECT * FROM material_zip_imports
 WHERE storage_path IS NOT NULL
   AND expires_at < #{now}
   AND status NOT IN ('IMPORTING')
 ORDER BY import_id ASC
 LIMIT #{limit}
